argv:
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
Add-Type @"
using System;
using System.Text;
using System.Runtime.InteropServices;
public static class W32PasteImg {
  public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowText(IntPtr hWnd, StringBuilder sb, int max);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetClassName(IntPtr hWnd, StringBuilder sb, int max);
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
}
"@
# Close any lingering Edge Open dialog.
$script:dlg=[IntPtr]::Zero
$cb=[W32PasteImg+EnumWindowsProc]{
 param($h,$l)
 $tsb=New-Object System.Text.StringBuilder 128
 $csb=New-Object System.Text.StringBuilder 64
 [void][W32PasteImg]::GetWindowText($h,$tsb,$tsb.Capacity)
 [void][W32PasteImg]::GetClassName($h,$csb,$csb.Capacity)
 if($tsb.ToString() -eq '開啟' -and $csb.ToString() -eq '#32770'){$script:dlg=$h; return $false}
 return $true
}
[W32PasteImg]::EnumWindows($cb,[IntPtr]::Zero)|Out-Null
if($script:dlg -ne [IntPtr]::Zero){
  [W32PasteImg]::SetForegroundWindow($script:dlg)|Out-Null
  [System.Windows.Forms.SendKeys]::SendWait('{ESC}')
  Start-Sleep -Milliseconds 700
}

$path='C:\Users\alston.huang\Downloads\Gemini_Generated_Image_iltypdiltypdilty.jpg'
if(-not (Test-Path -LiteralPath $path)){throw 'image path missing'}

$edge=Get-Process msedge -ErrorAction SilentlyContinue | Where-Object {$_.MainWindowHandle -ne 0} | Select-Object -First 1
if($null -eq $edge){throw 'Edge not visible'}
[W32PasteImg]::SetForegroundWindow($edge.MainWindowHandle)|Out-Null
Start-Sleep -Milliseconds 300
$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$composer=$null
for($i=0;$i -lt $all.Count;$i++){
  $e=$all.Item($i)
  if($e.Current.ControlType -eq [System.Windows.Automation.ControlType]::Edit -and [string]$e.Current.Name -like '文字欄位*新貼文*'){
    $composer=$e; break
  }
}
if($null -eq $composer){throw 'Threads composer not found'}
$composer.SetFocus()
Start-Sleep -Milliseconds 250

$img=[System.Drawing.Image]::FromFile($path)
try {
  [System.Windows.Forms.Clipboard]::SetImage($img)
  Start-Sleep -Milliseconds 250
  [System.Windows.Forms.SendKeys]::SendWait('^v')
} finally {
  $img.Dispose()
}
Start-Sleep -Seconds 7

$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$images=@()
$buttons=@()
for($i=0;$i -lt $all.Count;$i++){
  $e=$all.Item($i)
  $ct=$e.Current.ControlType.ProgrammaticName
  $r=$e.Current.BoundingRectangle
  if(-not [double]::IsInfinity($r.Y) -and $r.Y -gt 350 -and $r.Y -lt 950){
    if($ct -eq 'ControlType.Image'){
      $images += [pscustomobject]@{name=[string]$e.Current.Name;x=[string]$r.X;y=[string]$r.Y;w=[string]$r.Width;h=[string]$r.Height}
    } elseif($ct -eq 'ControlType.Button'){
      $n=[string]$e.Current.Name
      if($n -match '發佈|移除|刪除|編輯|裁切|媒體|影音|替代'){
        $buttons += [pscustomobject]@{name=$n;enabled=[bool]$e.Current.IsEnabled;x=[string]$r.X;y=[string]$r.Y;w=[string]$r.Width;h=[string]$r.Height}
      }
    }
  }
}
[pscustomobject]@{paste_attempted=$true;images=$images;buttons=$buttons}|ConvertTo-Json -Depth 5 -Compress
